// Regenerate docs/RULES.md from the rule catalog: `node scripts/gen-rules.ts`
import { writeFileSync } from 'node:fs';
import { RULES } from '../src/rules.ts';

const groups: [string, string][] = [
  ['SG1', 'Instructions a model will follow'],
  ['SG2', 'Data leaving the machine'],
  ['SG3', 'Code execution'],
  ['SG4', 'Persistence and tampering'],
  ['SG5', 'Destructive or weakening'],
  ['SG6', 'MCP servers'],
  ['SG7', 'Hooks'],
  ['SG8', 'Packaging'],
];

const out = [
  '# Rules',
  '',
  '<!-- Generated by scripts/gen-rules.ts from src/rules.ts. Do not edit by hand. -->',
  '',
  'Severity is the default; the scanner lowers it when the text is documentation, a test file, a fenced example, a quoted mention or a sentence phrased as a warning ("never …").',
  '',
  'Suppress a finding with a comment containing `skill-guard-ignore SG123` on the same line or the line above, `skill-guard-ignore-file SG123` anywhere in the file, or an entry in `.skill-guard.json`:',
  '',
  '```json',
  '{ "ignore": [{ "rule": "SG601", "item": "claude-code:mcp-server:*", "reason": "pinned via lockfile" }] }',
  '```',
  '',
];
for (const [prefix, title] of groups) {
  out.push(`## ${title}`, '');
  for (const r of RULES.filter((x) => x.id.startsWith(prefix))) {
    out.push(`### ${r.id} — ${r.title}`, '', `**Default severity:** ${r.severity}`, '', r.why, '', `**Fix:** ${r.fix}`, '');
  }
}
writeFileSync(new URL('../docs/RULES.md', import.meta.url), out.join('\n'));
console.log(`wrote docs/RULES.md (${RULES.length} rules)`);
